from collections import deque
def f(inp):
    h,w=len(inp),len(inp[0]); out=[r[:] for r in inp]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if inp[i][j]==1 and not seen[i][j]:
                # flood 1-region
                q=deque([(i,j)]);seen[i][j]=True;cells=[]
                while q:
                    a,b=q.popleft();cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        ca,cb=a+da,b+db
                        if 0<=ca<h and 0<=cb<w and inp[ca][cb]==1 and not seen[ca][cb]:
                            seen[ca][cb]=True;q.append((ca,cb))
                # bounding box of the region
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                interior={p for p in cells}
                inside=set()
                for a in range(r0,r1+1):
                    for b in range(c0,c1+1):
                        if (a,b) not in interior: inside.add((a,b))
                # paint interior with 3, border of region with 2, extend border outward by 1 ring of 2
                for a,b in interior: out[a][b]=3
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    for a,b in cells:
                        aa,bb=a+da,b+db
                        if 0<=aa<h and 0<=bb<w: out[aa][bb]=2
                for da in (-1,0,1):
                    for db in (-1,0,1):
                        if da==db==0: continue
                        for a,b in cells:
                            aa,bb=a+da,b+db
                            if 0<=aa<h and 0<=bb<w and out[aa][bb]!=2: out[aa][bb]=2
